import { apiFetch } from './client'
import type { GeoJSONPolygon, Zone, ZoneAssignment } from './types'

export function createZone(name: string, boundary: GeoJSONPolygon): Promise<Zone> {
  return apiFetch<Zone>('/api/v1/zones', {
    method: 'POST',
    body: JSON.stringify({ name, boundary }),
  })
}

export function getZones(): Promise<Zone[]> {
  return apiFetch<Zone[]>('/api/v1/zones')
}

export function getZone(zoneId: string): Promise<Zone> {
  return apiFetch<Zone>(`/api/v1/zones/${zoneId}`)
}

export function assignRepToZone(zoneId: string, repId: string): Promise<ZoneAssignment> {
  return apiFetch<ZoneAssignment>(`/api/v1/zones/${zoneId}/assignments`, {
    method: 'POST',
    body: JSON.stringify({ rep_id: repId }),
  })
}

export function getZoneAssignments(zoneId: string): Promise<ZoneAssignment[]> {
  return apiFetch<ZoneAssignment[]>(`/api/v1/zones/${zoneId}/assignments`)
}

